import java.util.*;

public class Armstrong {
    public static void main(String[] args) {
        int num = 153;
        int original = num;
        int digits = String.valueOf(num).length();
        int sum = 0;
        while (num != 0) {
            int digit = num % 10;
            sum += Math.pow(digit, digits);
            num /= 10;
        }
        if (sum == original) {
            System.out.println("Yes, the number is an Armstrong number.");
        } else {
            System.out.println("No, the number is not an Armstrong number.");
        }
    }
}

public class ReverseString {
    public static void main(String[] args) {
        String input = "hello";
        StringBuilder reversed = new StringBuilder();
        for (int i = input.length() - 1; i >= 0; i--) {
            reversed.append(input.charAt(i));
        }
        System.out.println(reversed.toString());
    }
}

public class Employee {
    String name;
    int id;
    double basic;

    Employee(String name, int id, double basic) {
        this.name = name;
        this.id = id;
        this.basic = basic;
    }

    double calculateGross() {
        double hra = basic * 0.20;
        double da = basic * 0.10;
        return basic + hra + da;
    }
}

public class SalaryDemo {
    public static void main(String[] args) {
        Employee emp = new Employee("John", 101, 50000);
        System.out.println("Gross Salary: " + emp.calculateGross());
    }
}

public abstract class Account {
    protected double balance;

    public Account(double balance) {
        this.balance = balance;
    }

    public void deposit(double amount) {
        balance += amount;
    }

    public abstract void withdraw(double amount);

    public double getBalance() {
        return balance;
    }
}

public class SavingsAccount extends Account {
    public SavingsAccount(double balance) {
        super(balance);
    }

    @Override
    public void withdraw(double amount) {
        if (amount <= balance) {
            balance -= amount;
        } else {
            System.out.println("Insufficient funds");
        }
    }
}

public class CurrentAccount extends Account {
    private double overdraftLimit = 1000;

    public CurrentAccount(double balance) {
        super(balance);
    }

    @Override
    public void withdraw(double amount) {
        if (amount <= balance + overdraftLimit) {
            balance -= amount;
        } else {
            System.out.println("Overdraft limit exceeded");
        }
    }
}

public class Book {
    private String title;
    private String author;
    private boolean issued;

    public Book(String title, String author) {
        this.title = title;
        this.author = author;
        this.issued = false;
    }

    public String getTitle() { return title; }
    public String getAuthor() { return author; }
    public boolean isIssued() { return issued; }
    public void setIssued(boolean issued) { this.issued = issued; }
}

import java.util.*;

public class Library {
    private List<Book> books = new ArrayList<>();

    public void addBook(Book b) {
        books.add(b);
    }

    public Book findByTitle(String title) {
        for (Book b : books) {
            if (b.getTitle().equalsIgnoreCase(title)) {
                return b;
            }
        }
        return null;
    }

    public boolean issueBook(String title) {
        Book b = findByTitle(title);
        if (b != null && !b.isIssued()) {
            b.setIssued(true);
            return true;
        }
        return false;
    }
}

public class LibraryDemo {
    public static void main(String[] args) {
        Library library = new Library();
        library.addBook(new Book("Effective Java", "Joshua Bloch"));
        boolean issued = library.issueBook("Effective Java");
        System.out.println("Issued: " + issued);
    }
}
